for n in N:
    fm = ['---',
    f'id: arXiv:{n["id"]}',
    f'title: "{n["title"]}"',
    f'title_zh: "{n["title_zh"]}"',
    f'track: {n["track"]}',
    f'venue: {n["venue"]}',
    f'date: {n["date"]}',
    f'value: {n["value"]}',
    f'grade: {n["grade"]}',
    f'evidence: {n["evidence"]}',
    'status: CURRENT',
    f'scores: {{IMP:{n["scores"]["IMP"]}, NOV:{n["scores"]["NOV"]}, TEC:{n["scores"]["TEC"]}, EXP:{n["scores"]["EXP"]}, PER:{n["scores"]["PER"]}, TRL:{n["scores"]["TRL"]}, REP:{n["scores"]["REP"]}}}',
    f'fetch_level: {"L0" if n["evidence"]=="FULL" else "-"}',
    '---', '',
    f'# {n["title_zh"]}', '',
    '> 批次：2026-10-19 补漏批次（公告日 ' + n['date'] + '，拉取日 2026-10-19，积压补漏非当日新提交）。', '',
    '## 一句话结论', n['conclusion'], '',
    '## 要解决的问题', n['problem'], '',
    '## 方法详解', n['method'], '',
    '## 实验与结果', n['experiments'], '',
    '## 局限与风险', ('证据等级为摘要级：本章数值与细节均为摘要口径，未在正文核实。' if n['evidence']=='ABSTRACT_ONLY' else '见论文原文。'), '',
    '## 与文献库的关系', n['relation'], '',
    '## 可复现性', n['repro']]
    fn = f'{OUT}/{n["id"]}__{n["slug"]}.md'
    open(fn, 'w', encoding='utf-8').write('\n'.join(fm))
    print('wrote', fn)
